<div class="hkp-head"><div><h1><?php echo hkp_e('Advisory frameworks'); ?></h1><p><?php echo hkp_e('Altus Performance Matrix™, GOPPAR Value Stack™, ESG and institutional capabilities, scored on a 1–5 scale. Scoring thresholds are configuration, not code.'); ?></p></div></div>
<div class="hkp-grid hkp-grid--2" style="margin-bottom:1rem">
<?php foreach ($fw as $f): ?><section class="hkp-card"><h2><?php echo hkp_h(hkp_pick($f, 'name')); ?></h2>
